INSERT INTO routes (id, kind, name, region, status, difficulty, distance_km, gain_m, loss_m, date_start, date_end, from_point, to_point, season, forecast_link, bus_link, bdz_link, avtogari_link, route_line, verification_level, transport, huts, risk, days, accommodation, taxis, windy_embed, notes_default) VALUES ('R06', 'detailed', 'Мусаленски', 'Рила', 'Планиран', 'Висока', 15, 690, 690, '', '', '', '', 'Юни – Октомври', 'https://www.google.com/search?q=windy+prognoza+Musala', '', 'https://razpisanie.bdz.bg/', 'https://avtogari.info/', 'Боровец → (маршрут по маркировка/Кайзеров път или директно от лифта) → заслон Еверест → вр. Мусала → х. Мусала/х. Марица → Радуил', 'СРЕДНО — комбинирани туристически описания и блогове потвърждават общата последователност и километри.', '{"summary":"Достъп до началото от Боровец е лесен с кола или лифт; крайна точка Радуил изисква трансфер/такси или автобус от Самоков/Радуил.","car":{"available":true,"text":"До курорт Боровец се стига по асфалт (София–Самоков–Боровец). Последните паркинги до лифта/началото са асфалтирани; при силни валежи внимателно за снежни/кални участъци през рана пролет/късна есен.","parkingNote":"Паркинг в Боровец/станция лифт; GPS паркинг ~42.185,23.633 (Боровец център) — проверете местни знаци/събития."},"public":{"steps":[{"from":"София","to":"Самоков","mode":"Автобус/микробус","time":"~1–1.5ч","note":"Чести линии до Самоков; оттам такси/автобус до Боровец."},{"from":"София","to":"Боровец","mode":"Sитнияково лифт + пеша","time":"лифт 10–20 мин + 3–4ч пеша","note":"Лифт сезонно; проверете работно време."}]}}'::jsonb, '[{"name":"заслон Еверест","elevation":null,"beds":null,"officialPhone":null,"altPhone":null,"email":null,"gps":null,"verified":true,"conflict":null},{"name":"хижа Мусала","elevation":2389,"beds":null,"officialPhone":"0896 661 454","altPhone":null,"email":null,"gps":"42.179,23.584","verified":true,"conflict":null},{"name":"хижа Марица (алтернативна за нощувка/приключване)","elevation":1480,"beds":null,"officialPhone":"0877 112 913","altPhone":null,"email":null,"gps":null,"verified":true,"conflict":"Налична в маршрутни описания като следваща след слизане; контакти не са потвърдени от 2 независими източника."}]'::jsonb, '{"level":"ВИСОК","color":"rose","points":["Технически: билни и каменисти участъци близо до вр. Мусала, силен вятър и открити участъци; маркировката е добра, но при мъгла ориентацията е трудна.","Инциденти: в описания и блогове има споменавания за изморяване и необходимост от спускане по заобиколни пътеки при лошо време; конкретни официални доклади не са намерени в първичните източници (непотвърдено).","Сезонност: рискът се повишава извън летния сезон (сняг, лед)."],"conclusion":"Маршрутът изисква добро планиране и опит при висока денивелация и билни условия."}'::jsonb, '[{"date":null,"label":"Боровец → заслон Еверест → вр. Мусала","type":"Преход (ден 1)","distance":"15 км (общо указание)","gain":"+690м","time":"6–8ч","stay":"заслон Еверест или х. Мусала","difficulty":"Висок"}]'::jsonb, '[{"name":"Хотел/вили в Боровец","location":"Боровец","rating":null,"price":null,"note":"Много опции за нощувка преди тръгване."},{"name":"Пансион/къщи в Радуил","location":"Радуил","rating":null,"price":null,"note":"Удобни за край на прехода, изискват трансфер."}]'::jsonb, '[{"name":"Такси Самоков","phone":null,"note":"Таксита обслужват курорта и организират трансфери до Радуил/Самоков; номера се променят — резервирайте предварително."}]'::jsonb, 'https://embed.windy.com/embed.html?type=map&location=coordinates&metricRain=mm&metricWind=km%2Fh&zoom=10&overlay=rain&product=ecmwf&level=surface&lat=42.179&lon=23.584', ''),
('R07', 'detailed', 'Панорамен', 'Рила', 'Планиран', 'Висока', 20, 800, 1100, '', '', '', '', 'Юни – Септември', 'https://www.google.com/search?q=windy+prognoza+Zavrachica', '', 'https://razpisanie.bdz.bg/', 'https://avtogari.info/', 'Боровец → (Кайзеров път/маркиран седловинен маршрут) → х. Заврачица → вр. Янчов чал → слизане към Якоруда', 'СРЕДНО — х. Заврачица и панорамни описания потвърждават маршрута и приблизителни стойности за км и денивелация.', '{"summary":"Началото е лесно достъпно от Боровец; край Якоруда има автобусни връзки, но чести трансфери са редки — такси/трансфер препоръчителни.","car":{"available":true,"text":"Паркинг в Боровец; до х. Заврачица могат да се подходи пеша от Боровец или с помощта на горски пътища в зависимост от вариантите.","parkingNote":"Проверете проходимост за последните незастроени километри при дъжд."},"public":{"steps":[{"from":"София","to":"Самоков","mode":"Автобус/влак + автобус/такси","time":"~1–2ч","note":"От Самоков до Боровец автобус/такси."},{"from":"Якоруда","to":"София/Благоевград","mode":"Автобус","time":"редки линии","note":"Проверете разписания предварително."}]}}'::jsonb, '[{"name":"хижа Заврачица","elevation":2178,"beds":75,"officialPhone":"0884791609","altPhone":null,"email":null,"gps":"42.168,23.640","verified":true,"conflict":null}]'::jsonb, '{"level":"ВИСОК","color":"rose","points":["Билни и открити участъци с силен вятър и експозиция; продължително излагане може да е опасно при лошо време.","Инциденти: няма ясно документирани сериозни инциденти в публичните блогове, но има репорти за изморяване и навлизане в мъгла (непотвърдено).","Сезонност: извън лятото частично нестабилни условия, сняг до късна пролет."],"conclusion":"Подходящ за опитни преходници, изисква подготовка и проверка на времето."}'::jsonb, '[{"date":null,"label":"Боровец → х. Заврачица → вр. Янчов чал → Якоруда","type":"Преход (ден 1)","distance":"20 км (прибл.)","gain":"+800м","time":"8–10ч","stay":"х. Заврачица или нощувка в Якоруда","difficulty":"Висок"}]'::jsonb, '[{"name":"Хотели/къщи в Якоруда","location":"Якоруда","rating":null,"price":null,"note":"Опции за нощувка след слизане."},{"name":"Хижата Заврачица","location":"м. Заврачица","rating":null,"price":null,"note":"Капацитет и контакти в планинските портали, но е добре да звъннете предварително."}]'::jsonb, '[{"name":"Локални таксита Якоруда/Самоков","phone":null,"note":"Резервация препоръчителна за трансфер от/до крайната точка."}]'::jsonb, 'https://embed.windy.com/embed.html?type=map&location=coordinates&metricRain=mm&metricWind=km%2Fh&zoom=10&overlay=rain&product=ecmwf&level=surface&lat=42.168&lon=23.640', ''),
('R08', 'detailed', 'Картала', 'Рила', 'Планиран', 'Средна', 15, 950, 950, '', '', '', '', 'Април – Октомври', 'https://www.google.com/search?q=windy+prognoza+Hut+Makedoniya', '', 'https://razpisanie.bdz.bg/', 'https://avtogari.info/', 'Благоевград → (трансфер/такси/автобус) → х. Македония → през билото/пътеки към Семково или Рилски манастир', 'ДОБРО — х. Македония е добре описана в туристически източници с надморска височина и капацитет.', '{"summary":"Крайни точки (Благоевград, Семково/Рилски манастир) имат автобусни връзки; началният достъп до х. Македония изисква трансфер/пешеходно навлизане по планински пътища.","car":{"available":false,"text":"До самата хижа Македония няма директен асфалтов достъп за лични коли (често се достига пеш/със специални 4x4 при договорен трансфер).","parkingNote":"Паркинг в Благоевград/Семково; уточнете за локални горски пътища."},"public":{"steps":[{"from":"Благоевград","to":"Семково/Рилски манастир","mode":"Автобус/микробус","time":"1–2ч","note":"Проверете редовността на линии към селата/кътовете."},{"from":"Семково","to":"хижа Македония","mode":"такси/трансфер/пеша","time":"перементно","note":"Често използват групови трансфери/таксита."}]}}'::jsonb, '[{"name":"хижа Македония","elevation":2166,"beds":40,"officialPhone":"0898564977","altPhone":null,"email":null,"gps":null,"verified":true,"conflict":"Статус и височина, както и контакт 089 856 4977, са посочени в туристически публикации и сайт Planinka; липсват допълнителни официални телефонни номера във видимите източници."}]'::jsonb, '{"level":"СРЕДЕН","color":"amber","points":["Терен: планински пътеки с изкачвания — не чрез технически участъци, но с дължина и износване; маркировката е смесена.","Инциденти: няма значими документирани сериозни случаи в общодостъпните ресурси.","Сезонност: зимен достъп изисква опит и екипировка."],"conclusion":"Подходящ за повечето добре подготвени туристи; осигурете логистика за трансфер."}'::jsonb, '[{"date":null,"label":"Благоевград → х. Македония","type":"Преход (ден 1)","distance":"~15 км (общо)","gain":"+950м","time":"6–8ч","stay":"хижа Македония","difficulty":"Среден"},{"date":null,"label":"хижа Македония → Семково/Рилски манастир","type":"Преход/спускане (ден 2)","distance":"зависи от варианта","gain":"-","time":"4–6ч","stay":"Семково/Рилски манастир или Благоевград","difficulty":"Среден"}]'::jsonb, '[{"name":"Хотели в Благоевград","location":"Благоевград","rating":null,"price":null,"note":"Удобен транспортен хъб преди/след прехода."},{"name":"хижа Македония","location":"в планината","rating":null,"price":"~20 лв (споменато в източник)","note":"Проверете актуални цени/места."}]'::jsonb, '[{"name":"Локални таксита Благоевград/Семково","phone":null,"note":"Резервация препоръчителна."}]'::jsonb, '', '')
